    protected override void ConfigureEntity(EntityTypeBuilder<NotificationDeliveryAttempt>b){Mapping.PublicId(b);Mapping.Long(b,nameof(NotificationDeliveryAttempt.NotificationDeliveryId),"notification_delivery_id");Mapping.Int(b,nameof(NotificationDeliveryAttempt.AttemptNo),"attempt_no");Mapping.DateTime(b,nameof(NotificationDeliveryAttempt.StartedAt),"started_at");Mapping.DateTime(b,nameof(NotificationDeliveryAttempt.CompletedAt),"completed_at",true);Mapping.String(b,nameof(NotificationDeliveryAttempt.ResultCode),"result_code",30,unicode:false);Mapping.String(b,nameof(NotificationDeliveryAttempt.ProviderResponseCode),"provider_response_code",100,unicode:false,nullable:true);Mapping.String(b,nameof(NotificationDeliveryAttempt.FailureReason),"failure_reason",1000,nullable:true);Mapping.Guid(b,nameof(NotificationDeliveryAttempt.CorrelationId),"correlation_id",true);Mapping.DateTime(b,nameof(NotificationDeliveryAttempt.CreatedAt),"created_at",utcDefault:true);Mapping.Fk<NotificationDeliveryAttempt,NotificationDelivery>(b,nameof(NotificationDeliveryAttempt.NotificationDeliveryId));b.HasIndex(x=>new{x.NotificationDeliveryId,x.AttemptNo}).IsUnique();}
