internal sealed class NotificationEventConfiguration() : EntityConfiguration<NotificationEvent>("notification_events")
{
    protected override void ConfigureEntity(EntityTypeBuilder<NotificationEvent>b){Mapping.PublicId(b);Mapping.Long(b,nameof(NotificationEvent.NotificationId),"notification_id");Mapping.NullableLong(b,nameof(NotificationEvent.NotificationRecipientId),"notification_recipient_id");Mapping.NullableLong(b,nameof(NotificationEvent.NotificationDeliveryId),"notification_delivery_id");Mapping.NullableLong(b,nameof(NotificationEvent.ActorUserId),"actor_user_id");Mapping.String(b,nameof(NotificationEvent.EventTypeCode),"event_type_code",50,unicode:false);Mapping.String(b,nameof(NotificationEvent.IdempotencyKey),"idempotency_key",180,unicode:false);Mapping.String(b,nameof(NotificationEvent.EventDataJson),"event_data_json",null,true);Mapping.DateTime(b,nameof(NotificationEvent.OccurredAt),"occurred_at");Mapping.DateTime(b,nameof(NotificationEvent.CreatedAt),"created_at",utcDefault:true);Mapping.Fk<NotificationEvent,Notification>(b,nameof(NotificationEvent.NotificationId));Mapping.Fk<NotificationEvent,NotificationRecipient>(b,nameof(NotificationEvent.NotificationRecipientId));Mapping.Fk<NotificationEvent,NotificationDelivery>(b,nameof(NotificationEvent.NotificationDeliveryId));Mapping.Fk<NotificationEvent,User>(b,nameof(NotificationEvent.ActorUserId));b.HasIndex(x=>x.IdempotencyKey).IsUnique();b.HasIndex(x=>new{x.NotificationId,x.OccurredAt});b.ToTable("notification_events",t=>t.HasCheckConstraint("CK_notification_events_data_json","[event_data_json] IS NULL OR ISJSON([event_data_json]) = 1"));}
